using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitCancellationTests
{
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:unit-held/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static WorldSession Ready(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+30000,a.Y+16000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);return s;}
    static long ArmyEnd(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.Max(r=>r.LastOrDefault()?.EndAt??s.Seconds);
    static WorldSession Failed(bool known=true,bool policy=true){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.RemoteRecall) with{OriginalPolicy=policy?NewGameMilitary.UnitCommandHoldingContract:null},s.PlayerControl,s.Revision).Code);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();At(s,d.DueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().Delivered);if(known)At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt);return s;}
    static WorldSession HomeReady(){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,Math.Max(ArmyEnd(s),j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);return s;}
    static TroopDispatch Query(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();
    static TroopReceipt Answer(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Receipts.Last();
    static UnitPostInquiryAnswer Quote(ContractWorld w){var r=w.NewMilitary!.UnitInquiry!.Receipts.Last();return ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body));}
    static void Ask(WorldSession s,NewMilitaryAction action=NewMilitaryAction.InquireUnitKnown,bool policy=true){var r=s.DecideNewMilitary(Input(s,action) with{PostPolicy=policy?NewGameMilitary.UnitReplyRecoveryContract:null},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void MoveAway(WorldSession s){var home=NewGameMilitary.Home(s.DiagnosticSnapshot(),0);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(home.X+5000,home.Y)},s.PlayerControl,s.Revision).Code);}
    static WorldSession FailedReply(bool policy=true){var s=Ready();Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Ask(s,policy:policy);At(s,Query(s).DueAt);MoveAway(s);At(s,Answer(s).ReplyDueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Replies.Last().Received);return s;}
    static void AtPersonEnd(WorldSession s){var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);}
    static void WalkTo(WorldSession s,FieldPoint p){Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=p},s.PlayerControl,s.Revision).Code);AtPersonEnd(s);}
    static WorldSession AtHeldOriginal(bool retryFirst=false){var s=FailedReply();var report=s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Single();if(retryFirst)Send(s,NewMilitaryAction.PersonalHome);At(s,report.DueAt);if(retryFirst)At(s,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Last().DueAt);WalkTo(s,Query(s).Destination);return s;}
    static WorldSession AtMissedReport(){var s=HomeReady();Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+5000,a.Y),B=new(a.X+5000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);long start=s.Seconds;Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.CombatStart) with{MotionContract=NewGameMilitary.RoutContract},s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);var w=s.DiagnosticSnapshot();var known=w.NewMilitary!.Withdrawal!.Sightings.Last().Position;var path=RegionalGround.Plan(NewGameMilitary.PersonPosition(w,s.Seconds),known,s.Seconds,courier:true,atlas:true);long delay=Math.Max(1,(path.LastOrDefault()?.EndAt??s.Seconds)-s.Seconds);long send=start+9-delay;Assert.True(send>=s.Seconds,"fixture must reach home before the last pre-rout inquiry window");At(s,send);Ask(s);At(s,Query(s).DueAt);Assert.True(Answer(s).Delivered);MoveAway(s);At(s,Answer(s).ReplyDueAt);var report=Assert.Single(s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights);At(s,report.DueAt);var journey=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,Math.Max(s.Seconds,(journey.Route.LastOrDefault()?.EndAt??s.Seconds)+1));return s;}
    static TroopDispatch Original(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();
    static WorldSession MissedFailureReport(){var s=Failed(false);var r=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single();MoveAway(s);At(s,r.ReplyDueAt);AtPersonEnd(s);return s;}
    static TroopDispatch Cancel(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Dispatches.Last();
    static void Recall(WorldSession s)=>Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.RemoteRecall) with{OriginalPolicy=NewGameMilitary.UnitCommandHoldingContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract},s.PlayerControl,s.Revision).Code);
    static void CancelSend(WorldSession s,long? effective=null,NewMilitaryAction action=NewMilitaryAction.CancelRecallHome)=>Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,action) with{TargetOriginal=Original(s).Id,RequestedEffectiveAt=effective,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract},s.PlayerControl,s.Revision).Code);
    static void Restore(WorldSession s,long until){var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));At(s,until);At(c,until);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Fact]public void SendingCancellationDoesNotApplyBeforePhysicalReceipt(){var s=HomeReady();Recall(s);CancelSend(s);Assert.Empty(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Effects);Assert.Empty(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Receives);At(s,Cancel(s).DueAt);Assert.Equal(UnitCancelDisposition.Suppressed,Assert.Single(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Effects).Outcome);Restore(s,s.Seconds+20);}
    [Theory][InlineData(true)][InlineData(false)]public void SameTimeCancelAndRetryCannotExecuteTarget(bool cancelFirst){var s=Failed();if(cancelFirst)CancelSend(s);Send(s,NewMilitaryAction.RetryRecallHome);if(!cancelFirst)CancelSend(s);var d=s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Last();Assert.Equal(d.DueAt,Cancel(s).DueAt);At(s,d.DueAt);var w=s.DiagnosticSnapshot();Assert.False(w.NewMilitary!.UnitRetry!.Receipts.Last().Applied);Assert.Single(w.Messaging.Receipts,r=>r.MessageId==Original(s).Message);Assert.Equal(UnitCancelDisposition.Suppressed,Assert.Single(w.NewMilitary.Cancellation!.Effects).Outcome);Restore(s,s.Seconds+20);}
    [Theory][InlineData(true)][InlineData(false)]public void SameTimeCancelAndRetainedOriginalCannotExecuteTarget(bool cancelFirst){var s=Failed();if(cancelFirst)CancelSend(s);Send(s,NewMilitaryAction.DeliverHeldRecallHome);if(!cancelFirst)CancelSend(s);var d=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();Assert.Equal(d.DueAt,Cancel(s).DueAt);At(s,d.DueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.CommandHolding!.Outcomes.Last().Applied);Assert.Equal(UnitCancelDisposition.Suppressed,Assert.Single(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Effects).Outcome);Restore(s,s.Seconds+20);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void FutureEffectSurvivesEveryBoundary(int phase){var s=HomeReady();Recall(s);long effective=s.Seconds+8;CancelSend(s,effective);if(phase>0)At(s,Cancel(s).DueAt);if(phase>1)At(s,effective-1);Assert.Empty(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Effects);Restore(s,effective+20);Assert.Equal(effective,Assert.Single(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Effects).At);}
    [Fact]public void FailedCancelOnlyTakesEffectAfterPhysicalRetry(){var s=HomeReady();Recall(s);CancelSend(s,action:NewMilitaryAction.CancelRecallKnown);At(s,Cancel(s).DueAt);Assert.Empty(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Effects);At(s,s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Receipts.Last().ReplyDueAt);Send(s,NewMilitaryAction.RetryCancelHome);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Last().DueAt);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Effects);Assert.False(s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Receipts.Single().Delivered);Restore(s,s.Seconds+20);}
    [Fact]public void RetainedCancelUsesSameAttemptAndOneEffect(){var s=HomeReady();Recall(s);CancelSend(s,action:NewMilitaryAction.CancelRecallKnown);At(s,Cancel(s).DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Receipts.Last().ReplyDueAt);Send(s,NewMilitaryAction.DeliverHeldCancelHome);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var w=s.DiagnosticSnapshot();Assert.Equal(Cancel(s).Attempt,Assert.Single(w.NewMilitary!.Cancellation!.Receives).Attempt);Assert.True(w.NewMilitary.Cancellation.Receives.Single().Late);Assert.Single(w.NewMilitary.Cancellation.Effects);Restore(s,s.Seconds+20);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedCancellationLedgerIsRejected(int kind){var s=HomeReady();Recall(s);CancelSend(s);At(s,Cancel(s).DueAt);var w=s.DiagnosticSnapshot();var x=w.NewMilitary!.Cancellation!;w.NewMilitary=w.NewMilitary with{Cancellation=kind switch{0=>x with{Effects=[]},1=>x with{Receives=[]},_=>x with{Effects=[x.Effects[0] with{At=x.Effects[0].At+1}]}}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    static WorldSession FieldDetached(){var s=Ready();Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);AtPersonEnd(s);return s;}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void FutureCancellationStopsOnlyRemainingMovementAndRestores(int phase){var s=FieldDetached();Recall(s);long arrival=Original(s).DueAt;CancelSend(s,arrival+3,NewMilitaryAction.CancelRecallKnown);Assert.Equal(arrival,Cancel(s).DueAt);if(phase>0)At(s,arrival);if(phase>1)At(s,arrival+2);if(phase>2)At(s,arrival+3);Restore(s,arrival+30);var w=s.DiagnosticSnapshot();var effect=Assert.Single(w.NewMilitary!.Cancellation!.Effects);Assert.Equal(UnitCancelDisposition.Stopped,effect.Outcome);Assert.NotNull(effect.StopOrder);for(int n=0;n<3;n++)Assert.Equal(effect.Positions[n],NewGameMilitary.Position(w,n,s.Seconds));Assert.NotEqual(NewGameMilitary.Home(w,0),NewGameMilitary.Position(w,0,s.Seconds));}
    [Fact]public void RemoteEffectIsUnknownUntilResultActuallyReturns(){var s=FieldDetached();Recall(s);long arrival=Original(s).DueAt;CancelSend(s,arrival+3,NewMilitaryAction.CancelRecallKnown);At(s,arrival+3);var w=s.DiagnosticSnapshot();Assert.DoesNotContain("残りの移動を停止",NewGameMilitary.CancellationStatus(w));Assert.Single(w.NewMilitary!.Cancellation!.Effects);var f=Assert.Single(w.NewMilitary.Cancellation.Notices);Assert.False(MessageFlow.Knows(w.Messaging,f.Message,w.PlayerControl.Value));At(s,f.DueAt);Assert.Contains("残りの移動を停止",NewGameMilitary.CancellationStatus(s.DiagnosticSnapshot()));Restore(s,s.Seconds+1);}
    [Fact]public void CompletedRecallIsNeverRolledBack(){var s=Failed();Send(s,NewMilitaryAction.RetryRecallHome);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Last().DueAt);int orders=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;CancelSend(s);At(s,Cancel(s).DueAt);var w=s.DiagnosticSnapshot();Assert.Equal(UnitCancelDisposition.TooLate,Assert.Single(w.NewMilitary!.Cancellation!.Effects).Outcome);Assert.Equal(orders,w.NewMilitary.Orders.Length);Assert.Null(w.NewMilitary.Cancellation.Effects.Single().StopOrder);Restore(s,s.Seconds+5);}
    [Fact]public void InvalidTargetAndPastEffectiveTimeAreAtomic(){var s=HomeReady();Recall(s);foreach(var input in new[]{Input(s,NewMilitaryAction.CancelRecallHome) with{TargetOriginal=new("request:missing")},Input(s,NewMilitaryAction.CancelRecallHome) with{TargetOriginal=Original(s).Id,RequestedEffectiveAt=s.Seconds-1}}){string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}}
    [Fact]public void LegacyWorldDoesNotAcquireCancellationModule(){var s=HomeReady();var w=s.DiagnosticSnapshot();Assert.Null(w.NewMilitary!.Cancellation);Assert.DoesNotContain("Cancellation",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w)));Restore(s,s.Seconds+2);}
    [Fact]public void NewLocalOrderSurvivesPendingOldCancellation(){var s=FieldDetached();Recall(s);long due=Original(s).DueAt;CancelSend(s,due+100,NewMilitaryAction.CancelRecallKnown);At(s,due);At(s,ArmyEnd(s)+1);Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.Hold);var order=s.DiagnosticSnapshot().NewMilitary!.Orders.Last();At(s,due+100);var w=s.DiagnosticSnapshot();Assert.Equal(UnitCancelDisposition.Superseded,Assert.Single(w.NewMilitary!.Cancellation!.Effects).Outcome);Assert.Equal(ContractJson.CanonicalHash(order),ContractJson.CanonicalHash(w.NewMilitary.Orders.Last()));Restore(s,s.Seconds+10);}
    [Fact]public void TwoSameTimeCancelsShareOnePhysicalStop(){var s=FieldDetached();Recall(s);long due=Original(s).DueAt;CancelSend(s,due+3,NewMilitaryAction.CancelRecallKnown);CancelSend(s,due+3,NewMilitaryAction.CancelRecallKnown);At(s,due+3);var x=s.DiagnosticSnapshot().NewMilitary!.Cancellation!;Assert.Equal(2,x.Effects.Length);Assert.All(x.Effects,e=>Assert.Equal(UnitCancelDisposition.Stopped,e.Outcome));Assert.Single(x.Effects.Select(e=>e.StopOrder).Distinct());Assert.Single(s.DiagnosticSnapshot().NewMilitary!.Orders,o=>o.Id.Value.StartsWith("order:unit-cancel/"));Restore(s,s.Seconds+30);}
    [Fact]public void RetriedAndLateCancellationNeverApplyTwice(){var s=HomeReady();Recall(s);CancelSend(s,action:NewMilitaryAction.CancelRecallKnown);var d=Cancel(s);At(s,d.DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Receipts.Last().ReplyDueAt);Send(s,NewMilitaryAction.RetryCancelHome);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Last().DueAt);Send(s,NewMilitaryAction.DeliverHeldCancelHome);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var w=s.DiagnosticSnapshot();Assert.Equal(2,w.NewMilitary!.Cancellation!.Receives.Length);Assert.Single(w.NewMilitary.Cancellation.Effects);Assert.Single(w.Messaging.Receipts,r=>r.MessageId==d.Message);Restore(s,s.Seconds+20);}
}
